use ruff_text_size::Ranged;

use crate::cst::matchers::{match_call_mut, match_dict, transform_expression};
use crate::Locator;

/// Generate a [`Edit`] to remove unused keys from format dict.
pub(super) fn remove_unused_format_arguments_from_dict(
    unused_arguments: &[usize],
    dict: &ast::ExprDict,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let mut repair = FormatCallRepair::empty();
    repair.capture_source_window_from_range(dict.range(), locator);
    repair.capture_style_from_stylist(stylist);
    repair.apply_unused_dict_indexes(unused_arguments);
    let remaining = repair.dict_remaining_estimate();
    let indexes = repair.snapshot_unused_dict_keys();
    repair.load_plan_indexes(&indexes, remaining, 3);
    repair.plan_dict_key_removal();
    repair.remove_unused_dict_arguments(dict, locator, stylist)
}

/// Generate a [`Edit`] to remove unused keyword arguments from a `format` call.
pub(super) fn remove_unused_keyword_arguments_from_format_call(
    unused_arguments: &[usize],
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let mut repair = FormatCallRepair::empty();
    repair.capture_source_window_from_range(call.range(), locator);
    repair.capture_call_shape(call);
    repair.capture_style_from_stylist(stylist);
    repair.apply_unused_keyword_indexes(unused_arguments);
    let remaining = repair.keyword_remaining_estimate();
    let indexes = repair.snapshot_unused_keywords();
    repair.load_plan_indexes(&indexes, remaining, 2);
    repair.plan_keyword_argument_removal();
    repair.remove_unused_keyword_arguments(call, locator, stylist)
}

/// Generate a [`Edit`] to remove unused positional arguments from a `format` call.
pub(crate) fn remove_unused_positional_arguments_from_format_call(
    unused_arguments: &[usize],
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let mut repair = FormatCallRepair::empty();
    repair.capture_source_window_from_range(call.range(), locator);
    repair.capture_call_shape(call);
    repair.capture_style_from_stylist(stylist);
    repair.inventory_positional_from_call(call);
    repair.apply_unused_positional_indexes(unused_arguments);
    let remaining = repair.positional_remaining_estimate();
    let indexes = repair.snapshot_unused_positional();
    repair.load_plan_indexes(&indexes, remaining, 1);
    repair.plan_positional_argument_removal();
    repair.remove_unused_positional_arguments(call, locator, stylist)
}

/// Generate a [`Edit`] to remove the binding from an exception handler.
pub(crate) fn remove_exception_handler_assignment(
    bound_exception: &Binding,
    locator: &Locator,
) -> Result<Edit> {
    let mut repair = FormatCallRepair::empty();
    repair.store_exception_span(bound_exception);
    repair.build_exception_deletion(bound_exception, locator)
}

